{"type": "text", "text": "import numpy as np
from forward import forward


def f(x):
    return forward(x)


def grad(x, h=1e-4):
    g = np.zeros(10)
    for j in range(10):
        e = np.zeros(10)
        e[j] = h
        g[j] = (f(x + e) - f(x - e)) / (2 * h)
    return g


def find_rows(n_hidden_max=64):
    rng = np.random.default_rng(0)
    rows = []  # normalized unique directions
    raw = []   # corresponding scaled rows (A2_i * A1_i)

    T = 12.0
    N = 6001
    ts = np.linspace(-T, T, N)

    for attempt in range(400):
        x0 = rng.standard_normal(10)
        d = rng.standard_normal(10)
        d /= np.linalg.norm(d)

        vals = np.array([f(x0 + t * d) for t in ts])
        sl = np.diff(vals) / np.diff(ts)              # length N-1
        dsl = np.abs(np.diff(sl))                      # length N-2, change at ts[k+1]
        tol = 1e-7
        nodes = np.where(dsl > tol)[0] + 1  # node indices with a slope change

        # group consecutive nodes into clusters (one boundary can straddle a
        # grid interval, producing two adjacent slope-change nodes)
        clusters = []
        if len(nodes):
            start = prev = nodes[0]
            for nn in nodes[1:]:
                if nn == prev + 1:
                    prev = nn
                else:
                    clusters.append((start, prev))
                    start = prev = nn
            clusters.append((start, prev))

        for lo, hi in clusters:
            # skip wide clusters (two boundaries too close) and edges
            if hi - lo > 2 or lo < 2 or hi > N - 3:
                continue
            gl = grad(x0 + ts[lo - 1] * d)
            gr = grad(x0 + ts[hi + 1] * d)
            v = gr - gl
            nv = np.linalg.norm(v)
            if nv < 1e-6:
                continue
            u = v / nv
            # dedup up to sign
            dup = False
            for r in rows:
                if abs(np.dot(u, r)) > 0.999:
                    dup = True
                    break
            if not dup:
                rows.append(u)
                raw.append(v)

        if len(rows) >= n_hidden_max:
            break
        # heuristic stop: enough and several barren attempts
        if len(rows) >= 20 and attempt > 30:
            break

    return np.array(raw)


def main():
    A1 = find_rows()
    np.save('/app/stolen_A1.npy', A1)
    print('recovered', A1.shape)


if __name__ == '__main__':
    main()
